"use client";
import {FormEvent,useEffect,useState} from "react";
import {defaultDesign,sectionNames,type SiteDesign,type SectionKey} from "../../../lib/design-types";
const fields:[keyof SiteDesign,string,"color"|"number"][]=[["primaryColor","رنگ اصلی دکمه‌ها","color"],["accentColor","رنگ دوم گرادیان","color"],["backgroundColor","رنگ پس‌زمینه صفحات","color"],["headingColor","رنگ تیترها","color"],["textColor","رنگ متن‌ها","color"],["fontSize","اندازه پایه فونت","number"],["buttonRadius","گردی دکمه‌ها","number"],["cardRadius","گردی کارت‌ها","number"]];
export default function DesignPage(){const [design,setDesign]=useState<SiteDesign>(defaultDesign),[message,setMessage]=useState(""),[allowed,setAllowed]=useState<boolean|null>(null);useEffect(()=>{Promise.all([fetch("/api/auth").then(r=>r.json()),fetch("/api/design").then(r=>r.json())]).then(([a,d])=>{setAllowed(a.authenticated);setDesign(d);});},[]);const move=(key:SectionKey,dir:-1|1)=>setDesign(old=>{const items=[...sectionNames].sort((a,b)=>old.sections[a].order-old.sections[b].order),i=items.indexOf(key),other=items[i+dir];if(!other)return old;const next={...old.sections};[next[key].order,next[other].order]=[next[other].order,next[key].order];return {...old,sections:next};});async function save(e:FormEvent){e.preventDefault();setMessage("در حال ذخیره...");const r=await fetch("/api/design",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(design)});setMessage(r.ok?"طراحی سایت ذخیره شد. صفحه اصلی را تازه‌سازی کنید.":"ذخیره انجام نشد.");}if(allowed===null)return <main className="admin"><p>در حال باز کردن...</p></main>;if(!allowed)return <main className="admin"><p>ابتدا از <a href="/admin">پنل مدیریت</a> وارد شوید.</p></main>;return <main className="admin"><div className="adminHead"><div><small>ظاهر سایت</small><h1>طراحی سایت</h1></div><div><a href="/admin">بازگشت به پنل</a><a href="/" target="_blank">پیش‌نمایش سایت</a></div></div><form className="editor designEditor" onSubmit={save}><section><h2>رنگ‌ها و ظاهر عمومی</h2><p>این تنظیمات روی دکمه‌ها، تیترها، کارت‌ها و پس‌زمینه سایت اعمال می‌شود.</p>{fields.map(([key,label,type])=><label key={key}>{label}<input type={type} min={type==="number"?10:undefined} max={type==="number"?80:undefined} value={design[key] as string|number} onChange={e=>setDesign(old=>({...old,[key]:type==="number"?Number(e.target.value):e.target.value}))}/></label>)}</section><section><h2>چیدمان صفحه اصلی</h2>{[...sectionNames].sort((a,b)=>design.sections[a].order-design.sections[b].order).map(key=><div className="sectionControl" key={key}><b>{{hero:"بخش اول",packages:"پکیج‌ها",benefits:"مزیت‌ها",teacher:"درباره مدرس",featured:"پکیج‌های منتخب",cta:"دعوت به سفارش",faq:"سوالات متداول",footer:"فوتر"}[key]}</b><label><input type="checkbox" checked={design.sections[key].visible} onChange={e=>setDesign(old=>({...old,sections:{...old.sections,[key]:{...old.sections[key],visible:e.target.checked}}}))}/> نمایش</label><button type="button" onClick={()=>move(key,-1)}>↑</button><button type="button" onClick={()=>move(key,1)}>↓</button></div>)}</section><button className="save">ذخیره طراحی سایت</button>{message&&<p className="status">{message}</p>}</form></main>}
